import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def calculate_ratio(n):
    if n < 4:
        return 0.0
    f_kn = combinations(n, 3)
    g_kn = combinations(n, 4)
    if f_kn == 0:
        return float('inf')
    ratio = (g_kn**3) / (f_kn**4)
    return ratio

# Verification of K6, K7, K8
r_k6 = calculate_ratio(6)
r_k7 = calculate_ratio(7)
r_k8 = calculate_ratio(8)

print(f"R(K6) = {r_k6}")
print(f"R(K7) = {r_k7}")
print(f"R(K8) = {r_k8}")
